from typing import List, Dict

from boto3.dynamodb.conditions import Key

from dynamodb.dynamodb_service import DynamoDBService, DynamoDBQueryRequest
from dynamodb.entity.todo_list.todo_list_entity import TodoListEntity
from util.logs import Log, LogEventType


class TodoListQueryResponse:
    def __init__(self, items: List[Dict], last_evaluated_key: dict):
        self.items = [TodoListEntity.from_dict(item) for item in items]
        self.last_evaluated_key = last_evaluated_key


class TodoListEntityRepo(DynamoDBService):

    def find_all_todo_lists(
        self, next_token: str, limit: int = None
    ) -> TodoListQueryResponse:
        try:
            exclusive_start_key = (
                {
                    "pk": "TODO_LIST",
                    "sk": f"{TodoListEntity.entity_type.value}#{next_token}",
                }
                if next_token
                else None
            )
            response = self.query(
                DynamoDBQueryRequest(
                    key_condition_expression=Key("pk").eq(
                        TodoListEntity.entity_type.value
                    ),
                    limit=limit,
                    exclusive_start_key=exclusive_start_key,
                )
            )
            return TodoListQueryResponse(
                items=response.items, last_evaluated_key=response.last_evaluated_key
            )
        except Exception as e:
            Log(data=str(e), event_type=LogEventType.DynamoDBException).exception()
            raise e

    def put_todo_list(self, todo_list: TodoListEntity):
        try:
            self.put_item(item=todo_list.to_dict())
        except Exception as e:
            Log(data=str(e), event_type=LogEventType.DynamoDBException).exception()
            raise e
